Definition ASV_LEAF_STACK : Z := 16.

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition svat_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SV p n i : Z) (rest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (p + i)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' SV (C8 (wz p) :: C8 (wz n) :: rest)
    /\ ACONST m'.                                                        (* [comment removed for export] *)

Definition svat_stmt : Prop := forall (SV p n i : Z) (rest : list cell) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m SV (C8 (wz p) :: C8 (wz n) :: rest) ->
  0 <= i < n -> 0 <= p -> p + n < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ASV_LEAF_STACK <= bv_unsigned sp ->
  (bv_unsigned sp <= SV \/ SV + Z.of_nat (cells_size (C8 (wz p) :: C8 (wz n) :: rest)) <= lo) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  aceil <= lo -> ACONST m ->
  accessible m SV 16 -> SV mod 8 = 0 ->
  0 < p ->                                                                    (* [comment removed for export] *)
  evt bsegs (svat_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SV p n i rest lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz SV) (wz i) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SV_INDEX) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Lemma sv2_side : forall W m m' SV,
  ACONST m -> accessible m SV 16 -> munch W m m' -> wmono bsegs m m' -> Forall awin W ->
  ACONST m' /\ accessible m' SV 16.
Proof.
  intros W m m' SV AC ASV MU WM FW. split.
  - eapply ACONST_frame; [exact AC| exact MU| exact WM|]. eapply Forall_impl; [| exact FW]. intros iv (K & _ & _). exact K.
  - eapply accessible_transport; [exact ASV| exact MU|]. destruct ASV as (A0 & A1 & _). intros x Hx.
    apply awin_outside_sh; [exact FW| lia].
Qed.
