Definition svrp_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SV p n k : Z) (rest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',          (* [comment removed for export] *)
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (SV, SV + 16)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' SV (C8 (wz (p + k)) :: C8 (wz (n - k)) :: rest)
    /\ ACONST m' /\ accessible m' SV 16.                                (* [comment removed for export] *)

Definition svrp_stmt : Prop := forall (SV p n k : Z) (rest : list cell) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m SV (C8 (wz p) :: C8 (wz n) :: rest) ->
  0 <= k <= n -> 0 <= p -> p + n < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ASV_LEAF_STACK <= bv_unsigned sp ->
  (bv_unsigned sp <= SV \/ SV + Z.of_nat (cells_size (C8 (wz p) :: C8 (wz n) :: rest)) <= lo) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  aceil <= lo -> ACONST m ->
  accessible m SV 16 -> SV mod 8 = 0 -> awin (SV, SV + 16) ->
  0 < p ->                                                                    (* [comment removed for export] *)
  evt bsegs (svrp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SV p n k rest lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz SV) (wz k) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SV_REMOVE_PREFIX) fc None m (seg_rom bsegs)).

